fn all_sequence_equal_length(seq: &Vec<Vec<i32>>) -> bool {
    // If the outer list is empty, by convention we return true.
    if seq.is_empty() {
        return true;
    }
    // Get the length of the first inner array
    let first_len = seq[0].len();
    // Check that every inner array has the same length as the first
    seq.iter().all(|inner| inner.len() == first_len)
}

fn main() {
    let a = vec![vec![1, 2, 3], vec![4, 5, 6], vec![7, 8, 9]];
    let b = vec![vec![1, 2], vec![3, 4, 5]];

    assert!(all_sequence_equal_length(&a));
    assert!(!all_sequence_equal_length(&b));

    println!("All tests passed!");
}